importScripts('monthly-core.js?v=15');
let active=0,controller,cellCache=new Map();
onmessage=async({data:{id,node,period,params,latitude,longitude}})=>{active=id;controller?.abort();controller=new AbortController();const signal=controller.signal;try{let records=cellCache.get(node);if(!records){const url=new URL('https://archive-api.open-meteo.com/v1/archive');for(const [k,v]of Object.entries({latitude,longitude,start_date:'2020-01-01',end_date:'2025-12-31',models:'era5',daily:'temperature_2m_max,temperature_2m_mean,precipitation_sum,sunshine_duration',timezone:'UTC',elevation:'nan',cell_selection:'nearest'}))url.searchParams.set(k,v);const response=await fetch(url,{cache:'no-store',signal});if(!response.ok)throw Error('Monthly climate API returned '+response.status);const data=await response.json();if(id!==active)return;if(data.utc_offset_seconds!==0||Math.abs(data.latitude-latitude)>1e-6||Math.abs(data.longitude-longitude)>1e-6)throw Error('Monthly API returned a different climate cell');records=MonthlyCore.fromAPI(data);cellCache.set(node,records);while(cellCache.size>12)cellCache.delete(cellCache.keys().next().value);}const selected=period==='mean'?records:records.filter(r=>r.year===Number(period));if(!selected.length)throw Error('Monthly climate period unavailable');postMessage({id,node,period,months:MonthlyCore.aggregate(selected,params)});}catch(e){if(id===active&&e.name!=='AbortError')postMessage({id,error:e.message});}};
